import {requireAgeEligibility} from '../_shared/age.ts';
import {consumeApiQuota, cors, HttpError, jsonBody, requireUser, respond, safeError} from '../_shared/http.ts';

// Auth requires upper/lowercase, a digit, and a symbol. The remaining 256 bits
// are generated by the platform CSPRNG and are never returned to the client.
function temporaryPassword(): string {
 const bytes=crypto.getRandomValues(new Uint8Array(32));
 return `Aa1!${Array.from(bytes,byte=>byte.toString(16).padStart(2,'0')).join('')}`;
}

function randomHex(): string {
 return Array.from(crypto.getRandomValues(new Uint8Array(32)),byte=>byte.toString(16).padStart(2,'0')).join('');
}

async function sha256Hex(value: string): Promise<string> {
 const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));
 return Array.from(new Uint8Array(hash),byte=>byte.toString(16).padStart(2,'0')).join('');
}

Deno.serve(async req => {
 let headers: HeadersInit = {};
 try {
  headers=cors(req); if(req.method==='OPTIONS') return new Response(null,{status:204,headers});
  if(req.method!=='POST') throw new HttpError(405,'Use POST.');
  const actor=await requireUser(req);
  if(!['admin','reception'].includes(actor.role)) throw new HttpError(403,'Staff management access required.');
  const body=await jsonBody(req,32768);
  const staff=body.action==='create_staff';
  if(!staff && body.action!=='import') throw new HttpError(400,'Invalid action.');
  if(Object.keys(body).some(key=>!(['action',...(staff?['age_13_or_older','email','full_name','phone','role']:['users'])].includes(key)))) throw new HttpError(400,'Unexpected request field.');
  if(staff && actor.role!=='admin') throw new HttpError(403,'Only administrators can create staff.');
  const users=staff?[body]:body.users;
  if(!Array.isArray(users)||users.length<1||users.length>100) throw new HttpError(400,'Provide between 1 and 100 accounts.');
  const emails=new Set<string>();
  for(const item of users) {
   if(!item || typeof item!=='object'||Array.isArray(item)) throw new HttpError(400,'Invalid account.');
   if(Object.keys(item).some(key=>!['age_13_or_older','email','full_name','phone','role',...(staff?['action']:['blood_group'])].includes(key))) throw new HttpError(400,'Unexpected account field.');
   requireAgeEligibility(item);
   if(typeof item.email!=='string'||item.email.length>254||! /^[^\s@<>]{1,64}@[a-z0-9-]+(?:\.[a-z0-9-]+)+$/i.test(item.email)||/@(example\.com|legacy\.com|test\.invalid)$/i.test(item.email)) throw new HttpError(400,'Every account needs a real, valid email address.');
   if(typeof item.full_name!=='string'||item.full_name.trim().length<2||item.full_name.length>150||/[<>\u0000-\u001f\u007f]/.test(item.full_name)) throw new HttpError(400,'Provide a plain-text name between 2 and 150 characters.');
   if(typeof item.phone!=='string'||!/^\d{11}$/.test(item.phone)) throw new HttpError(400,'Provide an 11-digit phone number.');
   if(!(staff?['reception','lab']:['donor','patient']).includes(item.role)) throw new HttpError(400,'Invalid account role.');
   if(!staff && !['A+','A-','B+','B-','AB+','AB-','O+','O-'].includes(item.blood_group)) throw new HttpError(400,'Provide a valid blood group.');
   const email=item.email.trim().toLowerCase(); if(emails.has(email)) throw new HttpError(400,'Remove duplicate emails before importing.'); emails.add(email);
  }
  await consumeApiQuota(actor,staff?'staff_create':'staff_import',users.length);
  const serviceKey=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  if(!serviceKey) throw new HttpError(503,'Account provisioning is not configured.');
  let created=0; const failed:number[]=[];
  for(let index=0;index<users.length;index++) {
   const item=users[index];
   try {
   const email=item.email.trim().toLowerCase();
   const staffInviteToken=staff?randomHex():null;
   if(staffInviteToken) {
    const prepared=await fetch(`${actor.url}/rest/v1/rpc/prepare_staff_provisioning`,{
     method:'POST',signal:AbortSignal.timeout(10000),
     headers:{Authorization:`Bearer ${serviceKey}`,apikey:serviceKey,'Content-Type':'application/json'},
     body:JSON.stringify({p_email:email,p_role:item.role,p_token_hash:await sha256Hex(staffInviteToken)}),
    });
    if(!prepared.ok) {failed.push(index+1);continue;}
   }
   const response=await fetch(`${actor.url}/auth/v1/admin/users`,{
    method:'POST',signal:AbortSignal.timeout(15000),headers:{Authorization:`Bearer ${serviceKey}`,apikey:serviceKey,'Content-Type':'application/json'},
    body:JSON.stringify({email,password:temporaryPassword(),
     // Account confirmation/recovery emails are TRANSACTIONAL ONLY; never add marketing.
     email_confirm:false,
     app_metadata:{lifelink_creation_source:'staff',...(staff?{lifelink_provisioned:true,role:item.role}:{})},
     user_metadata:{age_13_or_older:true,full_name:item.full_name.trim(),phone:item.phone,role:item.role,...(staffInviteToken?{staff_invite_token:staffInviteToken}:{}),...(!staff?{blood_group:item.blood_group}:{})}}),
   });
   if(response.ok) {
    const createdUser=await response.json();
    if(staff) {
     const recovery=await fetch(`${actor.url}/auth/v1/recover`,{method:'POST',signal:AbortSignal.timeout(15000),headers:{apikey:Deno.env.get('SUPABASE_ANON_KEY')!,'Content-Type':'application/json'},body:JSON.stringify({email:item.email.trim().toLowerCase()})});
     if(!recovery.ok) {
      if(typeof createdUser?.id==='string') await fetch(`${actor.url}/auth/v1/admin/users/${encodeURIComponent(createdUser.id)}`,{method:'DELETE',signal:AbortSignal.timeout(15000),headers:{Authorization:`Bearer ${serviceKey}`,apikey:serviceKey}});
      failed.push(index+1); continue;
     }
    }
    created++;
   } else failed.push(index+1);
   } catch (_) { failed.push(index+1); }
   // Deliberately do not log response bodies, passwords, or user identifiers.
  }
  if(staff && created===0) {
   return respond({error:'Staff account could not be created. Check whether the email is already registered; if not, try again or contact the administrator.'},409,headers);
  }
  return respond({created,failed_rows:failed,notice:staff?'A recovery code was sent. Staff must verify their email and choose their own password before first use.':'Imported accounts require account recovery and email verification before first use.'},200,headers);
 } catch(error) {return safeError(error,headers,'manage-users');}
});
